377: function MenuTemplates.CreateHighlightButton(text, onSelect, data, onEnter)
378: 	local optionDescription = CreateMenuElementDescription("WowMenuDropdownHighlightButtonTemplate");
379: 
380: 	local truncated = false;
381: 
382: 	local function OnEnter(button)
383: 		button.HighlightBGTex:SetAlpha(0.15);
384: 
385: 		if truncated then
386: 			local description = button:GetElementDescription();
387: 			MenuUtil.ShowTooltipEx(button, description:GetTooltipFrame(), function(tooltip)
388: 				GameTooltip_SetTitle(tooltip, text);
389: 			end);
390: 		end
391: 
392: 		if onEnter then
393: 			onEnter(data);
394: 		end
395: 	end
396: 
397: 	local function OnLeave(button)
398: 		button.HighlightBGTex:SetAlpha(0);
399: 
400: 		local description = button:GetElementDescription();
401: 		MenuUtil.HideTooltipEx(button, description:GetTooltipFrame());
402: 	end
403: 
404: 	optionDescription:AddInitializer(function(button, description, _menu)
405: 		button:SetScript("OnClick", function(_button, buttonName)
406: 			description:Pick(MenuInputContext.MouseButton, buttonName);
407: 		end);
408: 
409: 		if optionDescription:CanOpenSubmenu() then
410: 			MenuVariants.CreateSubmenuArrow(button);
411: 		end
412: 
413: 		CreateHighlightButtonText(button);
414: 
415: 		-- This button template is modified in Languages.lua to hide the text and display
416: 		-- a texture for each locale, so we need to redisplay the text. We don't have to worry
417: 		-- about that texture here because it is managed by the compositor.
418: 		button.Text:Show();
419: 		button.Text:SetTextToFit(text);
420: 		button.Text:SetWidth(button.Text:GetWidth() + 15);
421: 
422: 		button.HighlightBGTex:SetAlpha(0);
423: 
424: 		if description:IsEnabled() then
425: 			button.Text:SetTextColor(VERY_LIGHT_GRAY_COLOR:GetRGB());
426: 		else
427: 			button.Text:SetTextColor(DISABLED_FONT_COLOR:GetRGB());
428: 		end
429: 
430: 		truncated = button.Text:IsTruncated();
431: 
432: 		button:Layout();
433: 	end);
434: 
435: 	optionDescription:SetFinalInitializer(SetHighlightButtonFinalInitializer);
436: 	optionDescription:SetResponder(onSelect);
437: 	optionDescription:SetOnEnter(OnEnter);
438: 	optionDescription:SetOnLeave(OnLeave);
439: 	optionDescription:SetData(data);
440: 
441: 	return optionDescription;
442: end

374: 	button.NarrationGetIndexInfo = MenuButtonNarrationGetIndexInfo;
375: end
